What does this cycle detector return?

```python
def has_cycle(n, edges):
    p = list(range(n))
    def f(x):
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x
    for a, b in edges:
        ra, rb = f(a), f(b)
        if ra == rb:
            return (a, b)
        p[ra] = rb
    return None

print(has_cycle(4, [(0, 1), (1, 2), (2, 3), (3, 1)]))
```

This function is meant to return the 3 largest values. What does `top_k([9, 1, 8, 2, 7, 3], 3)` actually return?

```python
import heapq
def top_k(nums, k):
    h = []
    for x in nums:
        heapq.heappush(h, -x)
        if len(h) > k:
            heapq.heappop(h)
    return sorted(-v for v in h)
```

What does `median_bug([1, 2, 3, 4, 5])` return?

```python
import heapq
def median_bug(stream):
    lo, hi, out = [], [], []          # lo: max-heap (negated), hi: min-heap
    for x in stream:
        if not lo or x <= -lo[0]:
            heapq.heappush(lo, -x)
        else:
            heapq.heappush(hi, x)
        if len(lo) > len(hi) + 1:
            heapq.heappush(hi, -heapq.heappop(lo))
        out.append(-lo[0] if len(lo) > len(hi) else (-lo[0] + hi[0]) / 2)
    return out
```

